import { FastifyInstance } from 'fastify'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { system } from '../../../../src/app/helper/system/system'
import { AppSystemProp } from '../../../../src/app/helper/system/system-props'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers } from '../../../helpers/mcp-oauth'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance

const TLS_PROXY_HEADERS = {
    'x-forwarded-proto': 'https',
    'x-forwarded-host': 'mcp.customer.example.com',
}

async function discovery(headers: Record<string, string>): Promise<Record<string, string>> {
    const res = await app.inject({ method: 'GET', url: '/.well-known/oauth-authorization-server', headers })
    return res.json()
}

describe('MCP OAuth deployment shapes', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
    })

    afterAll(() => {
        vi.restoreAllMocks()
    })

    describe('behind a TLS-terminating proxy', () => {
        it('advertises https endpoints on the customer host, never the internal one', async () => {
            const metadata = await discovery(TLS_PROXY_HEADERS)

            for (const field of ['issuer', 'authorization_endpoint', 'token_endpoint', 'registration_endpoint', 'revocation_endpoint']) {
                expect(metadata[field], field).toMatch(/^https:\/\/mcp\.customer\.example\.com/)
            }
        })

        it('sends the consent redirect to the customer host so the browser can reach it', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: 'none' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: TLS_PROXY_HEADERS,
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/mcp\.customer\.example\.com\/mcp-authorize\?/)
        })

        it('points the protected resource metadata at the customer host', async () => {
            const res = await app.inject({
                method: 'GET',
                url: '/.well-known/oauth-protected-resource/mcp',
                headers: TLS_PROXY_HEADERS,
            })

            expect(res.json().resource).toBe('https://mcp.customer.example.com/mcp')
            expect(res.json().authorization_servers).toEqual(['https://mcp.customer.example.com'])
        })

        it('challenges an unauthenticated MCP call with a reachable metadata URL', async () => {
            const res = await app.inject({ method: 'POST', url: '/mcp', headers: TLS_PROXY_HEADERS })

            expect(res.statusCode).toBe(401)
            expect(res.headers['www-authenticate']).toContain('https://mcp.customer.example.com/.well-known/oauth-protected-resource/mcp')
        })
    })

    describe('hosted under a path prefix', () => {
        const PREFIXED_FRONTEND_URL = 'https://apps.customer.example.com/automation'

        beforeAll(() => {
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? PREFIXED_FRONTEND_URL : realGet(prop))
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? PREFIXED_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('advertises every endpoint under the configured prefix', async () => {
            const metadata = await discovery({ 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' })

            expect(metadata.issuer).toBe('https://apps.customer.example.com/automation')
            expect(metadata.token_endpoint).toBe('https://apps.customer.example.com/automation/token')
            expect(metadata.registration_endpoint).toBe('https://apps.customer.example.com/automation/register')
        })

        it('sends the consent redirect to the hostname root, the only path the app can route', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: 'none' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' },
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/apps\.customer\.example\.com\/mcp-authorize\?/)
        })
    })

    describe('with MCP served from its own hostname', () => {
        const DUAL_FRONTEND_URL = 'https://apps.customer.example.com/automation'
        const DUAL_MCP_URL = 'https://mcp.customer.example.com'
        const mcpHostHeaders = { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'mcp.customer.example.com' }
        const frontendHostHeaders = { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' }

        beforeAll(() => {
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => {
                if (prop === AppSystemProp.MCP_URL) {
                    return DUAL_MCP_URL
                }
                if (prop === AppSystemProp.FRONTEND_URL) {
                    return DUAL_FRONTEND_URL
                }
                return realGet(prop)
            })
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? DUAL_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('advertises the MCP host without the frontend path prefix', async () => {
            const metadata = await discovery(mcpHostHeaders)

            expect(metadata.issuer).toBe(DUAL_MCP_URL)
            expect(metadata.token_endpoint).toBe(`${DUAL_MCP_URL}/token`)
            expect(metadata.registration_endpoint).toBe(`${DUAL_MCP_URL}/register`)
        })

        it('keeps advertising the prefixed frontend base on the frontend host', async () => {
            const metadata = await discovery(frontendHostHeaders)

            expect(metadata.issuer).toBe(DUAL_FRONTEND_URL)
            expect(metadata.token_endpoint).toBe(`${DUAL_FRONTEND_URL}/token`)
        })

        it('points protected resource metadata at the MCP host', async () => {
            const res = await app.inject({
                method: 'GET',
                url: '/.well-known/oauth-protected-resource/mcp',
                headers: mcpHostHeaders,
            })

            expect(res.json().resource).toBe(`${DUAL_MCP_URL}/mcp`)
            expect(res.json().authorization_servers).toEqual([DUAL_MCP_URL])
        })

        it('challenges an unauthenticated MCP call on the MCP host with its own metadata URL', async () => {
            const res = await app.inject({ method: 'POST', url: '/mcp', headers: mcpHostHeaders })

            expect(res.statusCode).toBe(401)
            expect(res.headers['www-authenticate']).toContain(`${DUAL_MCP_URL}/.well-known/oauth-protected-resource/mcp`)
        })

        it('sends consent to the frontend origin, so the user signs in on the main host', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: 'none' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: mcpHostHeaders,
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/apps\.customer\.example\.com\/mcp-authorize\?/)
        })

        it('names each host as the OpenID issuer, so workload tokens still match on the frontend host', async () => {
            const onMcpHost = await app.inject({ method: 'GET', url: '/.well-known/openid-configuration', headers: mcpHostHeaders })
            const onFrontendHost = await app.inject({ method: 'GET', url: '/.well-known/openid-configuration', headers: frontendHostHeaders })

            expect(onMcpHost.json().issuer).toBe(DUAL_MCP_URL)
            expect(onFrontendHost.json().issuer).toBe(DUAL_FRONTEND_URL)
        })

        it('recognises the MCP host from an unchanged Host header when the proxy sends no X-Forwarded-Host', async () => {
            const metadata = await discovery({ 'host': 'mcp.customer.example.com', 'x-forwarded-proto': 'https' })

            expect(metadata.issuer).toBe(DUAL_MCP_URL)
        })

        it('leaves consent on the request host for a host matching neither setting', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: 'none' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'byo.customer.example.com' },
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/byo\.customer\.example\.com\/mcp-authorize\?/)
        })
    })

    describe('with an http AP_FRONTEND_URL behind a TLS-terminating proxy', () => {
        const HTTP_FRONTEND_URL = 'http://apps.customer.example.com'

        beforeAll(() => {
            vi.restoreAllMocks()
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => {
                if (prop === AppSystemProp.MCP_URL) {
                    return undefined
                }
                if (prop === AppSystemProp.FRONTEND_URL) {
                    return HTTP_FRONTEND_URL
                }
                return realGet(prop)
            })
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? HTTP_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('keeps the forwarded https scheme, as it did before AP_MCP_URL existed', async () => {
            const metadata = await discovery({ 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' })

            expect(metadata.issuer).toBe('https://apps.customer.example.com')
            expect(metadata.token_endpoint).toBe('https://apps.customer.example.com/token')
        })
    })
})

import { PrincipalType } from '@activepieces/shared'
import { FastifyBaseLogger } from 'fastify'
import { beforeAll, describe, expect, it, vi } from 'vitest'
import { jwtUtils } from '../../../../src/app/helper/jwt-utils'

const SECRET = 'verify-principal-test-secret'

vi.mock('../../../../src/app/user/user-service', () => ({
    userService: () => ({
        getOneOrFail: vi.fn().mockResolvedValue({
            id: 'user-1',
            identityId: 'identity-1',
            status: 'ACTIVE',
        }),
    }),
}))

vi.mock('../../../../src/app/authentication/user-identity/user-identity-service', () => ({
    userIdentityService: () => ({
        getOneOrFail: vi.fn().mockResolvedValue({
            id: 'identity-1',
            verified: true,
            tokenVersion: null,
        }),
    }),
}))

const { accessTokenManager } = await import('../../../../src/app/authentication/lib/access-token-manager')

const mockLog: FastifyBaseLogger = {
    debug: vi.fn(),
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    fatal: vi.fn(),
    trace: vi.fn(),
    child: vi.fn(),
    silent: vi.fn(),
    level: 'info',
} as unknown as FastifyBaseLogger

const manager = accessTokenManager(mockLog)

beforeAll(() => {
    vi.spyOn(jwtUtils, 'getJwtSecret').mockResolvedValue(SECRET)
})

describe('verifyPrincipal', () => {
    it('accepts a token with a valid PrincipalType', async () => {
        const token = await jwtUtils.sign({
            payload: {
                id: 'worker-1',
                type: PrincipalType.WORKER,
            },
            key: SECRET,
            expiresInSeconds: 60,
        })

        const decoded = await manager.verifyPrincipal(token)
        expect(decoded.id).toBe('worker-1')
        expect(decoded.type).toBe(PrincipalType.WORKER)
    })

    it('rejects a token whose type is not a PrincipalType', async () => {
        const token = await jwtUtils.sign({
            payload: {
                id: 'x',
                type: 'NOT_A_REAL_TYPE',
            },
            key: SECRET,
            expiresInSeconds: 60,
        })

        await expect(manager.verifyPrincipal(token)).rejects.toThrow()
    })

    it('rejects a token with no type field', async () => {
        const token = await jwtUtils.sign({
            payload: {
                id: 'x',
            },
            key: SECRET,
            expiresInSeconds: 60,
        })

        await expect(manager.verifyPrincipal(token)).rejects.toThrow()
    })
})

import {
  AIProviderWithoutSensitiveData,
  PlatformModelTier,
  PlatformModelTierEntry,
} from '@activepieces/shared';
import { t } from 'i18next';
import {
  ChevronRight,
  Eye,
  EyeOff,
  Loader2,
  Plus,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';
import { Input } from '@/components/ui/input';
import { Skeleton } from '@/components/ui/skeleton';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  KeyModelsById,
  modelMeta,
  PickableModel,
} from '@/features/agents/ai-model/model-meta';
import { platformModelTierMutations } from '@/features/platform-admin/hooks/platform-model-tier-hooks';
import { AdminControl, adminControl } from '@/lib/admin-control';
import { cn } from '@/lib/utils';

import { ModelDetailRow } from '../components/model-detail-row';
import { SectionHeader } from '../components/section-header';
import { KeyStatusBadge } from '../providers-tab/key-status';
import { ProviderLogo } from '../providers-tab/provider-logo';

export function SpecificModelsSection({
  tiers,
  ownKeys,
  keyModels,
  visible,
  projectsWithoutTier,
  onMakeTier,
}: SpecificModelsSectionProps) {
  const { mutate: setVisible, isPending } =
    platformModelTierMutations.useSetSpecificModelsVisible();
  const [search, setSearch] = useState('');
  const models = modelMeta.specificModelsOf({
    configs: ownKeys,
    keyModels,
    tiers,
  });
  const cannotHide = visible && tiers.length === 0;

  const needle = search.trim().toLowerCase();
  const matches = (item: PickableModel) =>
    needle === '' ||
    item.model.name.toLowerCase().includes(needle) ||
    item.model.id.toLowerCase().includes(needle);
  const groups = ownKeys
    .map((config) => {
      const keyMatches = config.name.toLowerCase().includes(needle);
      return {
        config,
        keyMatches,
        state: keyModels[config.id],
        items: models.filter(
          (item) =>
            item.config.id === config.id && (keyMatches || matches(item)),
        ),
      };
    })
    .filter(
      (group) => needle === '' || group.items.length > 0 || group.keyMatches,
    );

  return (
    <section className="flex flex-col rounded-xl border border-gray-6/60 bg-panel shadow-panel">
      <div className="flex flex-col gap-3 px-5 py-4">
        <div className="flex items-start justify-between gap-3">
          <SectionHeader
            title={t('Specific models')}
            count={models.length}
            description={t("Models not used as a tier's main model.")}
          />
          <div className="flex shrink-0 flex-col items-end gap-1">
            <div className="flex items-center gap-2">
              {isPending && (
                <Loader2
                  className="size-3.5 animate-spin text-gray-10"
                  aria-label={t('Saving')}
                />
              )}
              <Tabs
                value={visible ? 'visible' : 'hidden'}
                onValueChange={(value) => setVisible(value === 'visible')}
              >
                <TabsList
                  className="h-8"
                  aria-label={t('Specific models visible to builders')}
                  {...adminControl(
                    AdminControl.AI_SPECIFIC_MODELS_VISIBLE_TOGGLE,
                  )}
                >
                  <TabsTrigger
                    value="visible"
                    className="gap-1.5 text-xs"
                    disabled={isPending}
                  >
                    <Eye className="size-3.5" />
                    {t('Visible')}
                  </TabsTrigger>
                  <TabsTrigger
                    value="hidden"
                    className="gap-1.5 text-xs"
                    disabled={cannotHide || isPending}
                  >
                    <EyeOff className="size-3.5" />
                    {t('Hidden')}
                  </TabsTrigger>
                </TabsList>
              </Tabs>
            </div>
            <p className="text-xs text-gray-11">
              {cannotHide
                ? t('Add a tier before hiding these.')
                : visible
                ? t('Builders can pick these directly.')
                : t('Builders only see tiers.')}
            </p>
            {!cannotHide && projectsWithoutTier > 0 && (
              <p className="flex items-center gap-1 text-xs text-warning-11">
                <TriangleAlert className="size-3 shrink-0" />
                {visible
                  ? t('hidingLeavesProjectsEmpty', {
                      count: projectsWithoutTier,
                    })
                  : t('projectsWithNothingToPick', {
                      count: projectsWithoutTier,
                    })}
              </p>
            )}
          </div>
        </div>
        {models.length > SEARCH_THRESHOLD && (
          <Input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder={t('Search models')}
            aria-label={t('Search models')}
            className="max-w-sm"
          />
        )}
      </div>
      <div className="flex flex-col border-t border-gray-6/60">
        {groups.map((group) => (
          <KeyGroup
            key={group.config.id}
            config={group.config}
            items={group.items}
            total={
              models.filter((item) => item.config.id === group.config.id).length
            }
            hasTextModels={(group.state?.models?.length ?? 0) > 0}
            isLoading={group.state?.isLoading === true}
            isFetching={group.state?.isFetching === true}
            isError={group.state?.isError === true}
            onRetry={() => group.state?.refetch()}
            forceOpen={needle !== ''}
            defaultOpen={ownKeys.length === 1}
            onMakeTier={onMakeTier}
          />
        ))}
        {groups.length === 0 && (
          <p className="px-5 py-6 text-sm text-gray-11">
            {t('No models match')}
          </p>
        )}
      </div>
    </section>
  );
}

function KeyGroup({
  config,
  items,
  total,
  hasTextModels,
  isLoading,
  isFetching,
  isError,
  onRetry,
  forceOpen,
  defaultOpen,
  onMakeTier,
}: KeyGroupProps) {
  const [open, setOpen] = useState(defaultOpen);
  const [shown, setShown] = useState(PAGE_SIZE);
  const isOpen = forceOpen || open;
  const page = items.slice(0, shown);
  const retryButton = (
    <Button
      type="button"
      variant="ghost"
      size="icon-xs"
      aria-label={t('Retry')}
      disabled={isFetching}
      onClick={onRetry}
    >
      <RefreshCw className={cn('size-3', isFetching && 'animate-spin')} />
    </Button>
  );
  return (
    <Collapsible
      open={isOpen}
      onOpenChange={setOpen}
      className="border-b border-gray-6/60 last:border-b-0"
    >
      <div className="flex items-center gap-2 pr-5 hover:bg-gray-2">
        <CollapsibleTrigger asChild>
          <button
            type="button"
            className="flex min-w-0 flex-1 items-center gap-3 py-3 pl-5 text-left"
          >
            <ProviderLogo
              info={modelMeta.providerInfoOf({ provider: config.provider })}
            />
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate text-sm font-medium">
                {config.name}
              </span>
              <span className="text-xs text-gray-11">
                {isLoading ? (
                  <Skeleton className="h-3 w-20" />
                ) : isError ? (
                  t("Couldn't load {key} models", { key: config.name })
                ) : (
                  t('modelsCount', { count: total })
                )}
              </span>
            </span>
            <ChevronRight
              className={cn(
                'size-4 shrink-0 text-gray-10 transition-transform',
                isOpen && 'rotate-90',
              )}
            />
          </button>
        </CollapsibleTrigger>
        {config.status !== 'active' && (
          <KeyStatusBadge status={config.status} />
        )}
        {isError && retryButton}
      </div>
      <CollapsibleContent>
        <div className="flex flex-col pb-2 pl-16 pr-4">
          {isLoading &&
            [0, 1, 2].map((row) => (
              <div key={row} className="flex items-center gap-3 py-2.5">
                <Skeleton className="size-8 rounded-xl" />
                <div className="flex flex-1 flex-col gap-1.5">
                  <Skeleton className="h-3.5 w-40" />
                  <Skeleton className="h-3 w-24" />
                </div>
              </div>
            ))}
          {isError && (
            <div className="flex items-center gap-2 py-3 text-sm text-gray-11">
              <span>
                {t("Couldn't load {key} models", { key: config.name })}
              </span>
              {retryButton}
            </div>
          )}
          {page.map(({ model }) => (
            <ModelDetailRow
              key={model.id}
              name={model.name}
              config={config}
              model={model}
              nested
              trailing={
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    onMakeTier({ configId: config.id, modelId: model.id })
                  }
                  {...adminControl(AdminControl.AI_TIER_FROM_MODEL_OPEN)}
                >
                  <Plus className="size-4" />
                  {t('Make a tier')}
                </Button>
              }
            />
          ))}
          {!isLoading && !isError && items.length === 0 && (
            <p className="py-3 text-sm text-gray-11">
              {total > 0
                ? t('No models match')
                : hasTextModels
                ? t("Every text model on this key is a tier's main model.")
                : t('No text models on this key.')}
            </p>
          )}
          {items.length > page.length && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="self-start"
              onClick={() => setShown((current) => current + PAGE_SIZE)}
            >
              {t('Show {count} more', {
                count: Math.min(PAGE_SIZE, items.length - page.length),
              })}
            </Button>
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

const PAGE_SIZE = 20;
const SEARCH_THRESHOLD = 10;

type SpecificModelsSectionProps = {
  tiers: PlatformModelTier[];
  ownKeys: AIProviderWithoutSensitiveData[];
  keyModels: KeyModelsById;
  visible: boolean;
  projectsWithoutTier: number;
  onMakeTier: (entry: PlatformModelTierEntry) => void;
};

type KeyGroupProps = {
  config: AIProviderWithoutSensitiveData;
  items: PickableModel[];
  total: number;
  hasTextModels: boolean;
  isLoading: boolean;
  isFetching: boolean;
  isError: boolean;
  onRetry: () => void;
  forceOpen: boolean;
  defaultOpen: boolean;
  onMakeTier: (entry: PlatformModelTierEntry) => void;
};

import { ApEdition } from '@activepieces/shared'
import { MigrationInterface, QueryRunner } from 'typeorm'
import { isNotOneOfTheseEditions } from '../../database-common'

export class AddEnableEmailAuthToPlatform1704797979825
implements MigrationInterface {
    name = 'AddEnableEmailAuthToPlatform1704797979825'

    public async up(queryRunner: QueryRunner): Promise<void> {
        if (isNotOneOfTheseEditions([ApEdition.CLOUD, ApEdition.ENTERPRISE])) {
            return
        }
        await queryRunner.query(
            'ALTER TABLE "platform" ADD "emailAuthEnabled" boolean',
        )
        await queryRunner.query('UPDATE "platform" SET "emailAuthEnabled" = TRUE')
        await queryRunner.query(
            'ALTER TABLE "platform" ALTER COLUMN "emailAuthEnabled" SET NOT NULL',
        )
    }

    public async down(queryRunner: QueryRunner): Promise<void> {
        if (isNotOneOfTheseEditions([ApEdition.CLOUD, ApEdition.ENTERPRISE])) {
            return
        }
        await queryRunner.query(`
            ALTER TABLE "platform" DROP COLUMN "emailAuthEnabled"
        `)
    }
}

import { safeHttp } from '@activepieces/server-utils'
