    id: ApId
    type: PrincipalType.ONBOARDING
    tokenVersion?: string
}

export type PrincipalForType<T extends PrincipalType> = Extract<Principal, { type: T }>

export type PrincipalForTypes<R extends readonly PrincipalType[]> = PrincipalForType<R[number]>

export type Principal =
    | WorkerPrincipal
    | AnnonymousPrincipal
    | ServicePrincipal
    | UserPrincipal
    | EnginePrincipal
    | OnboardingPrincipal

import { FastifyInstance } from 'fastify'
import { accessTokenManager } from '../../src/app/authentication/lib/access-token-manager'
import { migrateQueuesAndRunConsumers } from '../../src/app/workers/worker-module'
import { setupTestEnvironment } from './test-setup'

export type E2eContext = {
    app: FastifyInstance
    workerToken: string
    apiUrl: string
}

export async function setupE2eEnvironment(): Promise<E2eContext> {
    // Use port 0 so the OS assigns a free port, avoiding EADDRINUSE in parallel test runs.
    const app = await setupTestEnvironment({ fresh: true })
    await app.listen({ port: 0, host: '127.0.0.1' })

    const address = app.server.address()
    const port = typeof address === 'object' && address !== null ? address.port : 3000
    const apiUrl = `http://127.0.0.1:${port}`

    process.env.AP_FRONTEND_URL = apiUrl
    process.env.AP_API_URL = apiUrl
    process.env.AP_PORT = String(port)

    await migrateQueuesAndRunConsumers(app)

    const workerToken = await accessTokenManager(app.log).generateWorkerToken()

    return { app, workerToken, apiUrl }
}

import { FastifyInstance } from 'fastify'
import { initializeDatabase } from '../../src/app/database'
import { databaseConnection, resetDatabaseConnection } from '../../src/app/database/database-connection'
import { databaseSeeds } from '../../src/app/database/seeds'
import { setupServer } from '../../src/app/server'

const GLOBAL_KEY = '__TEST_ENV__'

function getGlobalState(): TestGlobalState | undefined {
    return (globalThis as Record<string, unknown>)[GLOBAL_KEY] as TestGlobalState | undefined
}

function setGlobalState(state: TestGlobalState | undefined): void {
    (globalThis as Record<string, unknown>)[GLOBAL_KEY] = state
}

/**
 * Sets up the test environment. Reuses a shared DB/server singleton across test files.
 * Pass `{ fresh: true }` to force a new server — required for tests that use
 * vi.spyOn on server-internal modules, since the shared server captures module
 * references from the first evaluation.
 */
export async function setupTestEnvironment(opts?: { fresh?: boolean }): Promise<FastifyInstance> {
    if (opts?.fresh) {
        return createFreshEnvironment()
    }

    const existing = getGlobalState()
    if (existing) {
        await cleanDatabase()
        return existing.app
    }

    return createFreshEnvironment()
}

export async function teardownTestEnvironment(): Promise<void> {
    // No-op for shared mode; fresh mode destroys in next setupTestEnvironment call
}

async function createFreshEnvironment(): Promise<FastifyInstance> {
    const existing = getGlobalState()
    if (existing) {
        await existing.app.close()
        await databaseConnection().destroy()
    }
    resetDatabaseConnection()
    await initializeDatabase({ runMigrations: false })
    const app = await setupServer()
    giveInjectedRequestsASocketThatCanBeClosed(app)
    setGlobalState({ app })
    return app
}

function giveInjectedRequestsASocketThatCanBeClosed(app: FastifyInstance): void {
    app.addHook('onRequest', async (request) => {
        request.raw.socket.destroySoon ??= () => undefined
    })
}

async function cleanDatabase(): Promise<void> {
    const ds = databaseConnection()
    const entities = ds.entityMetadatas
    const tableNames = entities.map(e => `"${e.tableName}"`).join(', ')
    if (tableNames.length > 0) {
        await ds.query(`TRUNCATE TABLE ${tableNames} CASCADE`)
    }
    await databaseSeeds.run()
}

