type Request = {
    method: string;
    url: string;
    headers?: Record<string, string>;
    queryParams?: Record<string, string>;
    body?: unknown;
    responseType?: string;
    retries?: number;
};

type ConversionReply = { status?: number; body: unknown };

type AuthValue = { type: AppConnectionType.SECRET_TEXT; secret_text: string };

type OptionalKeys<Value> = {
    [Key in keyof Value]-?: undefined extends Value[Key] ? Key : never;
}[keyof Value];

type LoosePropsValue<Value> = Omit<Value, OptionalKeys<Value>> & Partial<Pick<Value, OptionalKeys<Value>>>;

type RunInput<Props extends InputPropertyMap> = {
    propsValue: LoosePropsValue<StaticPropsValue<Props>>;
    files?: ReturnType<typeof makeFiles>;
};

type StoredOutput = {
    file: string;
    file_name: string;
    file_extension?: string | null;
    file_size?: number | null;
    conversion_cost?: number | null;
};

import { httpClient, HttpMethod } from '@activepieces/pieces-common';
import { createAction, OAuth2PropertyValue, Property } from '@activepieces/pieces-framework';
import { trueLayerCommon } from '../../common';

export const startPaymentAuthorizationFlow = createAction({
  auth: trueLayerCommon.auth,
  name: 'start-payment-authorization-flow',
  classification: 'WRITE',
  displayName: 'Start Payment Authorization Flow',
  description: 'Start the authorization flow for a payment. This API can be called using the `resource_token` associated with the payment or a backend bearer token.',
  audience: 'both',
  aiMetadata: { description: 'Begin the authorization flow for an existing payment, returning the first action the user must take (e.g. provider selection or redirect). Use after create-payment to start driving the user through authorization. This mutates the payment\'s flow state and should be called once per payment, not repeatedly.', idempotent: false },
  props: {
    id: Property.ShortText({
      displayName: 'Payment ID',
      description: 'The ID of the payment for which to start the authorization flow.',
      required: true,
    }),
  },
  run: async (ctx) => {
    const response = await  httpClient.sendRequest({
      method: HttpMethod.POST,
      url: `${trueLayerCommon.baseUrl}/v3/payments/${ctx.propsValue.id}/authorization-flow`,
      headers: {
        Authorization: `Bearer ${(ctx.auth as OAuth2PropertyValue).access_token}`,
      },
      body: ctx.propsValue,
    })

    return response.body;
  },
});

import { FastifyInstance } from 'fastify'
import { createServiceContext, createTestContext, TestContext, TestContextParams } from './test-context'

export function describeWithAuth(
    name: string,
    getApp: () => FastifyInstance,
    fn: (setup: () => Promise<TestContext>) => void,
    params?: TestContextParams,
): void {
    describe.each(['USER', 'SERVICE'] as const)(`${name} [%s]`, (authType) => {
        const setup = async (): Promise<TestContext> => {
            const userCtx = await createTestContext(getApp(), params)
            if (authType === 'SERVICE') {
                return createServiceContext(getApp(), userCtx)
            }
            return userCtx
        }
        fn(setup)
    })
}

import { DefaultProjectRole } from '@activepieces/shared'
import { FastifyInstance } from 'fastify'
import { StatusCodes } from 'http-status-codes'
import { createMemberContext, createTestContext, TestContext } from './test-context'

export function describeRolePermissions(config: RolePermissionConfig): void {
    const {
        app,
        request,
        allowedRoles,
        forbiddenRoles,
        beforeEach: beforeEachFn,
    } = config

    if (allowedRoles.length > 0) {
        it.each(allowedRoles)('Succeeds if user role is %s', async (role) => {
            const ctx = await createTestContext(app())
            const memberCtx = await createMemberContext(app(), ctx, { projectRole: role })
            if (beforeEachFn) {
                await beforeEachFn(ctx)
            }
            const response = await request(memberCtx, ctx)
            expect(response.statusCode).not.toBe(StatusCodes.FORBIDDEN)
        })
    }

    if (forbiddenRoles.length > 0) {
        it.each(forbiddenRoles)('Fails if user role is %s', async (role) => {
            const ctx = await createTestContext(app())
            const memberCtx = await createMemberContext(app(), ctx, { projectRole: role })
            if (beforeEachFn) {
                await beforeEachFn(ctx)
            }
            const response = await request(memberCtx, ctx)
            expect(response.statusCode).toBe(StatusCodes.FORBIDDEN)

            const responseBody = response.json()
            expect(responseBody?.code).toBe('PERMISSION_DENIED')
            expect(responseBody?.params?.userId).toBe(memberCtx.user.id)
            expect(responseBody?.params?.projectId).toBe(ctx.project.id)
        })
    }
}

type RolePermissionConfig = {
    app: () => FastifyInstance
    request: (memberCtx: TestContext, ownerCtx: TestContext) => ReturnType<FastifyInstance['inject']>
    allowedRoles: DefaultProjectRole[]
    forbiddenRoles: DefaultProjectRole[]
    beforeEach?: (ctx: TestContext) => Promise<void>
}
